def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining < 0, -np.inf, -remaining)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining < 0, -np.inf, -(remaining ** 2) / bins + 0.1 * remaining)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target = bins * 0.25
    return np.where(remaining < 0, -np.inf, -np.abs(remaining - target))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    ideal = bins * 0.5
    return np.where(remaining < 0, -np.inf, -((remaining - ideal) ** 2))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    fill_ratio = item / bins
    return np.where(remaining < 0, -np.inf, -np.abs(0.5 - fill_ratio))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining < 0, -np.inf, -np.exp(-remaining ** 2))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target = bins * 0.75
    return np.where(remaining < 0, -np.inf, -np.expm1(np.abs(remaining - target)))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, remaining, -1e9 + remaining)
